def is_sublist(l, s):
    """Write a function to check whether a list contains the given sublist or not."""
    if len(s) == 0:
        return True
    if len(s) > len(l):
        return False
    for i in range(len(l) - len(s) + 1):
        if l[i : i + len(s)] == s:
            return True
    return False
